import {execFileSync} from 'node:child_process';import {appendFileSync} from 'node:fs';import {pathToFileURL} from 'node:url';import path from 'node:path';
export function visualApplicable(paths){if(!Array.isArray(paths)||!paths.every(p=>typeof p==='string'&&p&&!p.startsWith('/')&&!p.split(/[\\/]/).includes('..')))throw Error('invalid changed paths');return paths.some(p=>/^(frontend\/|e2e\/|scripts\/agent-workflows\/|\.github\/agent-workflows-|\.github\/workflows\/agent-evidence\.yml$)/.test(p));}
export function aggregate(needs){const errors=[];if(needs?.changes?.result!=='success')errors.push('change discovery failed or missing');if(needs?.validators?.result!=='success')errors.push('required validators failed or missing');const visual=needs?.changes?.outputs?.visual;if(!['true','false'].includes(visual))errors.push('visual applicability missing');if(visual==='true'&&needs?.visual?.result!=='success')errors.push('required visual evidence failed or missing');if(visual==='false'&&!['success','skipped'].includes(needs?.visual?.result))errors.push('unexpected visual job outcome');return {ok:errors.length===0,visualRequired:visual==='true',errors};}
if(process.argv[1]&&import.meta.url===pathToFileURL(path.resolve(process.argv[1])).href){try{if(process.argv[2]==='select'){const {BASE_SHA,HEAD_SHA,GITHUB_OUTPUT}=process.env;if(![BASE_SHA,HEAD_SHA].every(s=>/^[a-f0-9]{40}$/.test(s??'')))throw Error('exact base/head SHAs required');const paths=execFileSync('git',['diff','--name-only','-z',BASE_SHA,HEAD_SHA],{encoding:'utf8'}).split('\0').filter(Boolean);const visual=visualApplicable(paths);appendFileSync(GITHUB_OUTPUT,`visual=${visual}\n`);console.log(JSON.stringify({baseRevision:BASE_SHA,sourceRevision:HEAD_SHA,visualRequired:visual,changedPaths:paths}));}else if(process.argv[2]==='aggregate'){const result=aggregate(JSON.parse(process.env.JOB_RESULTS??'null'));console.log(JSON.stringify(result,null,2));if(!result.ok)process.exitCode=1;}else throw Error('require select or aggregate');}catch(e){console.error(e.message);process.exitCode=1;}}
